/**
 * A device enrolled the way a browser enrols one: keys generated by mero-js,
 * certified by a real account root standing in for the wallet.
 */
import {
  accountForRootPublicKey,
  beginDeviceEnrolment,
  completeDeviceEnrolment,
  mintDeviceId,
  signDeviceCert,
  signerFromSecret,
  type BegunDeviceEnrolment,
  type DeviceEnrolmentCallback,
} from '@calimero-network/mero-js';

/** The wallet's answer for `begun`, certified by `rootSecret`. */
export async function walletAnswer(
  begun: BegunDeviceEnrolment,
  rootSecret = '11'.repeat(32),
): Promise<DeviceEnrolmentCallback> {
  const root = await signerFromSecret(rootSecret, 'rootSecret');
  const account = await accountForRootPublicKey(root.publicKey);
  const device = await mintDeviceId(account, crypto.getRandomValues(new Uint8Array(16)));
  const credential = await signDeviceCert({
    signer: root,
    device,
    signPublicKey: begun.devicePublicKey,
    kemPublicKey: begun.kemPublicKey,
    deviceEpoch: 1,
  });
  return { credential, account, device, state: begun.state };
}

/** Enrol a device for the account `rootSecret` derives, and return its credential. */
export async function enrolledDevice(rootSecret?: string) {
  const enrolled = await completeDeviceEnrolment(await walletAnswer(await beginDeviceEnrolment(), rootSecret));
  return { account: enrolled.account, credential: enrolled.credential, signer: enrolled.signer };
}

/** Every record in mero-js's device store, as script on the origin sees it. */
export async function deviceRecords(): Promise<unknown[]> {
  const db = await new Promise<IDBDatabase>((resolve, reject) => {
    const req = indexedDB.open('calimero');
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  try {
    if (!db.objectStoreNames.contains('device')) return [];
    return await new Promise((resolve, reject) => {
      const req = db.transaction('device', 'readonly').objectStore('device').getAll();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  } finally {
    db.close();
  }
}
